在分布式系统中，客户端通过请求标识保证幂等性。服务端将结果写入缓存，并在超时后安全重试。下面的代码展示了异步请求和异常处理流程。

```typescript
export async function fetchTranslationWithRetry(providerEndpoint: string, requestIdentifier: string, sourceMarkdownDocument: string): Promise<string> {
  const maximumRetryAttempts = 3;
  for (let currentAttempt = 0; currentAttempt < maximumRetryAttempts; currentAttempt++) {
    const response = await fetch(providerEndpoint, { method: "POST", headers: { "Content-Type": "application/json", "Idempotency-Key": requestIdentifier }, body: JSON.stringify({ sourceMarkdownDocument }) });
    if (response.ok) return await response.text();
  }
  throw new Error("Translation request exceeded maximum retry attempts");
}
